PVD("myanmar_sector_myanmar-climate-change-strategy-2018-30",{"docs":["","Myanmar Climate Change Strategy 2018 30"],"s":{"1":[[1,"25","20","Climate-responsive policy environment","Build a climate-responsive policy environment",""]],"2":[[1,"24","14","Climate strategy institutional coordination mechanism (also read at p.25 §23; p.27 §21; p.60 §6; p.89 §6; p.102 §24; p.133 §15; p.134 §21; p.135 §9)","A multi-stakeholder institutional mechanism to coordinate action across",""]],"3":[[1,"26","3","Climate finance mobilisation and allocation mechanism (also read at p.27 §22; p.97 §9; p.99 §5; p.99 §8; p.111 §26; p.118 §10; p.133 §16; p.142 §9)","A financial mechanism to mobilise and allocate finance for inclusive",""]],"4":[[1,"26","10","Multi-stakeholder climate partnerships (also read at p.60 §12; p.141 §28)","Build functional multi-stakeholder partnerships",""]],"5":[[1,"26","12","Climate-smart investment policy framework (also read at p.27 §19; p.133 §13)","An overarching policy framework to guide coherent investment in climate-",""]],"6":[[1,"27","24","Climate actor capacity-strengthening framework (also read at p.133 §18; p.143 §9; p.144 §17)","A capacity-strengthening framework to enhance the capacity of actors across",""]],"7":[[1,"28","3","Climate strategy monitoring, evaluation and learning framework (also read at p.145 §9; p.145 §15; p.145 §21; p.145 §25)","A monitoring evaluation and learning framework to guide evidence-based",""]],"8":[[1,"40","5","Skills development programmes (also read at p.54 §8; p.140 §33; p.114 §8)","invest in skills development programmes",""]],"9":[[1,"40","20","Environmentally sound town development","Establishment of environmentally sound towns",""]],"10":[[1,"40","22","Tax system streamlining reform","Streamlining the tax system to increase national tax revenues.",""]],"11":[[1,"60","3","Climate-smart farming systems strategy","Strategise actions on climate-smart farming systems",""]],"12":[[1,"60","8","Climate-smart agriculture and livestock financing framework","Strengthen the financing framework for climate-smart agriculture, livestock",""]],"13":[[1,"61","14","Forest reforestation and restoration through REDD+","Reforesting and restoring 50 percent of Myanmar's degraded forests using REDD+",""]],"14":[[1,"66","11","Climate policy, regulatory and institutional strengthening","Formulating policies, strengthening regulations and building institutional",""]],"15":[[1,"66","17","Climate-resilient livelihood diversification support","Support climate-resilient livelihood diversification",""]],"16":[[1,"68","14","Low-emission urban public transportation systems","develop low-cost, low-emission public transportation systems in urban areas",""]],"17":[[1,"70","19","Renewable energy expansion (also read at p.74 §13; p.127 §23)","maximising renewable energy production from hydro and solar sources",""]],"18":[[1,"72","6","Myanmar climate change policy and strategy development (also read at p.91 §24; p.92 §29; p.109 §8; p.122 §24; p.123 §3; p.134 §8)","developing the Myanmar Climate Change Policy, Strategy and Master Plan",""]],"19":[[1,"74","15","Energy efficiency improvement in productive processes (also read at p.106 §5)","The improvement of energy efficiency in productive processes",""]],"20":[[1,"74","16","Climate change mainstreaming capacity development","The development of capacities to include climate change considerations",""]],"21":[[1,"75","2","Environmental regulations implementation","proactively implement environmental regulations",""]],"22":[[1,"78","23","Climate-integrated national housing framework","National Housing Framework, which should integrate climate change",""]],"23":[[1,"84","10","Disaster emergency relief fund","Disaster Emergency Relief Fund has been established",""]],"24":[[1,"84","24","Community-based disaster preparedness and risk reduction","Community-based disaster preparedness and risk reduction",""]],"25":[[1,"85","3","Disaster risk reduction plan update","update or develop a new plan to address DRR",""]],"26":[[1,"85","4","End-to-end early warning system development (also read at p.85 §7)","develop end-to-end early warning",""]],"27":[[1,"85","11","Emergency operation centre establishment","plans to set up an emergency operation centre",""]],"28":[[1,"86","12","Climate change integration into disaster management","climate change needs to be integrated into disaster management",""]],"29":[[1,"87","11","Climate change education and awareness programmes (also read at p.89 §11; p.105 §26; p.144 §18)","Awareness-raising programmes to strengthen awareness on climate change",""]],"30":[[1,"89","8","Environmental education and research improvement in tertiary institutions","Improvement of environmental education and research at tertiary",""]],"31":[[1,"91","13","Technology transfer for climate-resilient and low-carbon development","technology transfer for climate-resilient and low-carbon development",""]],"32":[[1,"99","24","Climate finance reporting and procurement systems (also read at p.145 §4)","reporting and procurement systems to manage climate finance effectively",""]],"33":[[1,"100","9","Public financial management reform","public finance management reform project",""]],"34":[[1,"100","10","Systematic devolution of funds framework","establish a more systematic approach for the devolution of funds",""]],"35":[[1,"100","24","Environmental impact and strategic environmental assessment use","uses environmental impact assessment and strategic",""]],"36":[[1,"102","19","Local climate information systems education initiative","strengthen its information systems for local people by educating",""]],"37":[[1,"116","9","Energy- and resource-efficient building design and construction","New buildings are designed and constructed to be energy and resource",""]],"38":[[1,"116","22","Climate-responsive health systems strengthening","strengthen climate-responsive health systems",""]],"39":[[1,"117","28","Climate-resilient and low-carbon development solutions","design and implement climate-resilient and low-carbon development solutions",""]],"40":[[1,"144","25","Climate change integration in education curricula","Integrating climate change into the education curricula",""]],"41":[[1,"145","13","Climate resilience and low-carbon target-setting support","Support decision makers to set targets for climate resilience and low-carbon",""]],"42":[[1,"145","14","Climate vulnerability and emissions baseline establishment","Establish a climate vulnerability and emission baseline",""]],"43":[[1,"145","23","Results-based climate change framework","Develop a results-based framework to identify adaptation and mitigation",""]]}});
PVD("myanmar_sector_myanmar-digital-economy-roadmap-2030",{"docs":["","Myanmar Digital Economy Roadmap 2030"],"s":{"1":[[1,"2","7","National high-capacity digital infrastructure development","Build country-wide high-capacity digital infrastructure to ensure accessibility, availability, and affordability.",""]],"2":[[1,"2","8","Digital economy growth and competitiveness promotion (also read at p.5 §3)","Boost the economy with digital technology i.e. driving a new S-Curve, raising competitiveness, building new businesses as well as creating values.",""]],"3":[[1,"2","9","Digital technology legal and regulatory reform (also read at p.23 §10)","Build trust and confidence in the use of digital technology by updating laws and regulations, encouraging investment and ensuring security in digital data and transactions.",""]],"4":[[1,"3","2","Digital economy development committee establishment","Established Digital Economy Development Committee (DEDC) in June 2017",""]],"5":[[1,"5","2","Digital identity card system","Data ID card system",""]],"6":[[1,"9","2","Digital technology use in business and trade (also read at p.15 §3)","Digital technology use in business and trade",""]],"7":[[1,"14","3","Digital trade and e-commerce promotion (also read at p.23 §4)","Digital Trade and E-Commerce promotion policy and support.",""]],"8":[[1,"14","4","Digital payment system policy development","Digital payment system policy development",""]],"9":[[1,"14","8","Tax relief for student computer and laptop imports","Tax Relief for Computer and Laptop Imports for Students",""]],"10":[[1,"14","9","Tax incentives for SME digital technology adoption (also read at p.23 §7)","SME businesses to widely use digital technologies through tax incentives.",""]],"11":[[1,"14","11","Digital economy advisory board establishment","Establish an Advisory Board of Domestic and International Experts",""]],"12":[[1,"14","13","Digital economy master plan development","Digital Economy Master Plan development",""]],"13":[[1,"15","5","Digital technology application for system efficiency","use digital technology to improve system efficiency",""]],"14":[[1,"16","4","Digital citizen engagement platform","Digital Citizen Engagement Platform",""]],"15":[[1,"17","9","Fiber optic and internet network connection for universities","Fiber Optic Network Connection and Internet Network Construction",""]],"16":[[1,"17","12","Universal service strategy for telecommunications expansion (also read at p.24 §11)","Universal Service Strategy",""]],"17":[[1,"18","8","International cybersecurity cooperation strengthening","Strengthen Cooperation with International Organizations for Cybersecurity",""]],"18":[[1,"18","10","Cyber security operation center establishment","Cyber Security Operation Center",""]],"19":[[1,"19","4","Digital literacy training expansion (also read at p.19 §15)","Expand Digital Literacy Training",""]],"20":[[1,"19","5","Digital community center expansion","Digital Community Center",""]],"21":[[1,"19","6","Innovation center establishment in major cities","Establish Innovation Centers in Major Cities",""]],"22":[[1,"19","10","Vocational training, internship and industrial attachment programme","Vocational Training, Internship program and industrial attachment",""]],"23":[[1,"19","12","Technopreneur education programme","Technopreneur Education Program",""]],"24":[[1,"20","2","Digital content creation in Myanmar and ethnic languages","Digital Content creation in Myanmar and ethnic languages",""]],"25":[[1,"20","6","Massive open online courses and online learning modules","massive open online course and online learning modules",""]],"26":[[1,"20","8","Digital and technical language teaching skills training for basic education teachers","Digital and technical language teaching skills training for basic education teachers",""]],"27":[[1,"21","4","Digital economy investment promotion (also read at p.25 §4)","investment promotion policy",""]],"28":[[1,"21","7","Special visa scheme for digital talent and tech investors (also read at p.25 §7)","Special Visa and Digital Talent Visa Scheme",""]],"29":[[1,"21","8","Intellectual property rights protection legislation (also read at p.25 §8)","Intellectual property rights protection legislation",""]],"30":[[1,"21","9","Research and development for emerging technologies (also read at p.25 §9)","Research and Testing of Emerging Technologies",""]],"31":[[1,"22","3","Digital economy zone establishment","Establish Digital Economy Zones",""]],"32":[[1,"22","4","Incubation, acceleration and innovation center development","incubation center, acceleration center and innovation center",""]],"33":[[1,"22","7","Open data policy and data sharing framework (also read at p.23 §11; p.25 §12; p.24 §15)","Open Data policy should be developed to enable innovation through the use of data.",""]],"34":[[1,"24","6","Public and urban fiber network expansion","Public and Urban Fiber Network Expansion",""]],"35":[[1,"24","8","Right of way facilitation and inter-ministerial coordination for network rollout","Right of Way Facilitation and Inter-Ministerial Coordination",""]]}});
PVD("myanmar_sector_myanmar-national-education-strategic-plan-2016-21",{"docs":["","Myanmar National Education Strategic Plan 2016 21"],"s":{"1":[[1,"6","3","National education sector reform roadmap (also read at p.9 §6)","a comprehensive, widely-owned and evidence-based roadmap intended to reform the entire education sector over the next five years",""]],"2":[[1,"9","5","Comprehensive education sector review and evidence base development (also read at p.16 §5; p.16 §6)","the Ministry of Education (MOE) has undertaken a three-and-a-half-year Comprehensive Education Sector Review (CESR)",""]],"3":[[1,"7","1","Quality play-centred preschool and kindergarten expansion (also read at p.14 §17; p.28 §4; p.28 §8; p.29 §6; p.29 §7; p.30 §7; p.30 §8)","The government is committed to expanding access to quality preschool and kindergarten education",""]],"4":[[1,"29","8","Preschool access grants for disadvantaged and remote areas","Expand access to school- and community-based preschools through preschool grants to disadvantaged areas",""]],"5":[[1,"29","9","Early childhood intervention services for children with special needs","Early childhood intervention services for children with special needs aged three to five years",""]],"6":[[1,"18","12","Preschool quality improvement (also read at p.30 §1; p.30 §2; p.30 §3; p.30 §4; p.29 §4)","Improve preschool quality to better prepare children for primary school",""]],"7":[[1,"18","13","Preschool governance and coordination strengthening (also read at p.29 §1)","Strengthen governance and co-ordination of preschool services",""]],"8":[[1,"29","3","ECCD committee establishment for preschool expansion","Establish ECCD Committees at district and township levels",""]],"9":[[1,"30","5","National preschool standards quality assurance assessments","Quality assurance assessments of the achievement of national preschool standards in all preschools",""]],"10":[[1,"30","10","Parental involvement promotion in kindergarten education","Promotion of parental involvement in kindergarten education",""]],"11":[[1,"30","11","Kindergarten teacher specialisation training","Implement a national teacher training programme for kindergarten specialisation",""]],"12":[[1,"14","7","Free compulsory primary education (also read at p.14 §14; p.16 §8; p.18 §5; p.34 §2; p.15 §4; p.16 §2; p.7 §8; p.21 §13; p.21 §16; p.15 §11; p.22 §6; p.27 §5; p.33 §12)","implement free, compulsory primary education system",""]],"13":[[1,"15","9","Free education service provision to reduce household burden","Establish effective education services that do not place a burden on parents and communities",""]],"14":[[1,"7","2","Basic education completion and learning competency improvement (also read at p.24 §8)","ensure that all children successfully complete their primary, middle and high school education and acquire relevant learning competencies",""]],"15":[[1,"35","8","Universal access to basic education","Universal access to basic education programme",""]],"16":[[1,"7","3","Targeted education programmes for disadvantaged and marginalised learners (also read at p.15 §1)","education programmes to be especially developed to meet the needs of children who face difficulties in accessing primary and secondary education",""]],"17":[[1,"15","2","Support for nationalities' languages and cultures in primary education (also read at p.36 §16)","Support and promote nationalities’ languages and cultures",""]],"18":[[1,"34","2","Mother tongue and inclusive education policy (also read at p.18 §6; p.31 §14; p.35 §1; p.35 §2; p.35 §3; p.35 §4)","allows for the learning of natioanlities’ languages and culture, and the use of natioanlities’ languages as a classroom language",""]],"19":[[1,"15","5","School facilities and equipment upgrading in less developed areas","Prioritise the needs of schools in less developed areas",""]],"20":[[1,"17","1","School infrastructure expansion and upgrading (also read at p.17 §2; p.17 §3; p.17 §3; p.30 §9; p.35 §10)","Expanding access to basic education — major investments in school infrastructure",""]],"21":[[1,"35","11","Teaching and learning materials provision for disadvantaged basic education schools","Provision of teaching and learning materials packages for basic education schools and students, prioritising schools in disadvantaged areas",""]],"22":[[1,"35","16","Support for at-risk students through remedial education, stipends and school feeding","remedial education, stipends and school feeding",""]],"23":[[1,"35","14","Compulsory primary education enrolment, return and retention pilot (also read at p.35 §15)","testing mechanisms and processes to enrol, return and retain children in schools with high numbers of students dropping out",""]],"24":[[1,"7","4","Basic education curriculum reform for twenty-first century skills (also read at p.19 §4; p.36 §6; p.36 §10; p.36 §12; p.36 §13; p.36 §14; p.20 §8)","redesign and launch a new basic education curriculum that focuses on relevant 21st century knowledge and skills",""]],"25":[[1,"36","15","Curriculum materials development and distribution (also read at p.37 §3; p.37 §6; p.37 §7)","Development and finalisation of curriculum materials",""]],"26":[[1,"19","5","Curriculum development team and teacher capacity building for curriculum implementation (also read at p.24 §10; p.36 §1; p.36 §2; p.36 §3)","Upgrading the professional capacity of curriculum development teams, as well as the capacity of head teachers and teachers to successfully implement the new curriculum",""]],"27":[[1,"36","5","Capacity development for curriculum developers of nationalities' languages","Capacity development for curriculum developers of nationalities’ languages in states and regions",""]],"28":[[1,"19","6","Curriculum management, dissemination and monitoring system strengthening (also read at p.37 §1; p.37 §2)","Strengthening curriculum management, dissem- ination and monitoring and evaluation systems",""]],"29":[[1,"37","4","New curriculum public dissemination campaign","Implement new curriculum dissemination through different media to stakeholders, including the public and parents",""]],"30":[[1,"19","9","Comprehensive basic education assessment reform (also read at p.38 §2; p.38 §5; p.39 §3)","Development and implementation of a comprehensive assessment policy for basic education schools",""]],"31":[[1,"20","1","Assessment capacity development for educators and officials (also read at p.20 §2)","A well-designed capacity development programme needs to be put in place focusing on assessment strategies, test development and analysis",""]],"32":[[1,"20","6","Comprehensive teacher management reform","comprehensive and integrated teacher management reforms that will strengthen teacher recruitment, deployment and retention",""]],"33":[[1,"20","7","Teacher education institution improvement","improve the quality of teaching, learning, infrastructure and management in teacher education institutions",""]],"34":[[1,"20","11","Alternative education policy framework","develop and widely disseminate an alternative education policy",""]],"35":[[1,"7","5","Alternative education programmes for out-of-school youth and adults (also read at p.12 §4; p.15 §6; p.16 §4; p.20 §12)","quality, accessible, flexible and certified alternative education programmes",""]],"36":[[1,"20","13","National quality standards for alternative education providers","establishing and actively measuring national quality standards for all government, non-government, community-based and private sector alternative education service providers",""]],"37":[[1,"20","14","Alternative education coordination strengthening","strengthen and expand co-ordination in the alternative education sub-sector",""]],"38":[[1,"7","7","Technical and vocational education and training expansion and quality improvement (also read at p.15 §8; p.21 §3; p.24 §2; p.21 §10)","expand and strengthen the quality of technical and vocational education and training",""]],"39":[[1,"21","4","TVET management and coordination framework strengthening","TVET management and co-ordination needs to be strengthened through a more cohesive legislative and policy framework",""]],"40":[[1,"15","7","Higher education autonomy and research reform","universities have autonomy over their own curriculum and governance and the ability to conduct independent research",""]],"41":[[1,"21","9","Higher education student support to overcome cost barriers","Support programmes are needed to help students to overcome cost barriers for higher education",""]],"42":[[1,"35","5","School leadership and management training","School leadership and management training to build the capacity of school leaders",""]],"43":[[1,"7","9","Parent engagement and PTA strengthening in education (also read at p.18 §7; p.21 §14; p.33 §6; p.33 §7)","parents should be encouraged and assisted to play a more active role in their children’s education",""]],"44":[[1,"14","6","Law enabling public participation in education","enact the necessary law to enable National people to participate in matters of their education and health",""]],"45":[[1,"22","2","Education stakeholder consultation process","organised 107 meetings with 3,199 stakeholders to discuss and document feedback",""]],"46":[[1,"31","12","Decision-making decentralisation for schools and townships (also read at p.31 §12; p.33 §3; p.33 §4)","Decision Making in Schools and Townships Policy",""]],"47":[[1,"33","11","Basic education reform communication campaign","Basic education reforms communication campaign",""]],"48":[[1,"22","5","Education reform sequencing, coordination and systems approach (also read at p.31 §8)","The NESP has adopted a comprehensive systems approach to education reforms",""]],"49":[[1,"35","9","School census and mapping baseline for access planning","School census and mapping baseline in all preschools and basic education schools",""]],"50":[[1,"15","10","Transparent education funding allocation and use","Ensure the effective, efficient and transparent allocation and use of government, private sector, other domestic and international funding",""]],"51":[[1,"21","7","Education governance reform toward performance, accountability and autonomy","a more corporate model that focuses on performance, accountability and autonomy",""]],"52":[[1,"39","4","Classroom and school student assessment system (also read at p.39 §5)","Classroom-level assessment to provide teachers and students with formative and summative assessment information about student learning achievement",""]],"53":[[1,"39","7","National sample-based student assessment system","National sample-based assessments to provide useful evidence about the level of student achievement in identified curriculum areas",""]],"54":[[1,"39","10","Education assessment coordination, management and monitoring programme","Strengthening co-ordination, management and monitoring programme",""]],"55":[[1,"39","11","Restructuring of the Department of Myanmar Examinations","Restructure of Department of Myanmar Examinations so that it has the human resources to successfully implement the basic education assessment reforms",""]],"56":[[1,"39","12","Assessment and examinations capacity building for ministry officers","Capacity building and advocacy to enable MOE assessment officers to develop, deliver and maintain high-quality assessment and examinations systems",""]],"57":[[1,"39","13","Assessment ICT infrastructure development","Development of assessment-related information and communication technology infrastructure to improve current work processes and the provision of examinations related services",""]],"58":[[1,"39","14","Examinations and assessments monitoring mechanisms","Development of monitoring mechanisms to track achievements regarding Grade 5, Grade 9 and end-of-high school completion examinations and national sample-based assessments",""]],"59":[[1,"40","2","Integrated teacher education and management reform","This demands an integrated approach to teacher education and management reform.",""]],"60":[[1,"40","3","Evidence-based teacher management and deployment system","the KG+12 expansion of basic education will require additional teachers to be placed using an evidence-based teacher management, planning and deployment system.",""]],"61":[[1,"40","4","In-service teacher training for the new basic education curriculum (also read at p.41 §14)","The planned introduction of a new basic education curriculum will demand establishment of a quality, cost-effective in-service training programme that can train all teachers on how to use new curriculum materials and sustain changes in pedagogy.",""]],"62":[[1,"40","5","Pre-service teacher education reform","pre-service teacher education also requires complementary reforms to enable teaching that bridges theory and practice and encourages self-reflective practice.",""]],"63":[[1,"40","7","Teacher quality assurance and management strengthening (also read at p.40 §8)","Strengthen teacher quality assurance and teacher management",""]],"64":[[1,"40","9","Teacher Education Council establishment","Establishment of a Teacher Education Council to enable teacher representatives to advise and support implementation of the teacher education and management reforms in the NESP",""]],"65":[[1,"40","10","Teacher quality assurance system","Establishment of a teacher quality assurance system against which teachers can be held to account for quality teaching and measurable improvements in student learning",""]],"66":[[1,"40","11","Equitable teacher recruitment, promotion and deployment system","Design and implementation of an equitable teacher recruitment, promotion and deployment system to improve management and achieve an appropriate teacher-student ratio",""]],"67":[[1,"41","2","Pre-service teacher education quality improvement programme","Pre-service teacher education quality improvement  programme",""]],"68":[[1,"41","3","Teacher education curriculum and training module revision","Short-term revisions to the teacher education curriculum and training modules to ensure that they are aligned with the NESP basic education reforms",""]],"69":[[1,"41","4","Upgrading education college programmes to specialised degree courses (also read at p.41 §9)","Upgrading two-year programmes in education colleges to Specialised degree programmes",""]],"70":[[1,"41","5","School partnerships and practicum reform for teacher trainees","School partnerships and reform of block teaching and practicum to ensure that teacher trainees have the opportunity to apply their learning and gain essential feedback and advice as they develop their teaching practice",""]],"71":[[1,"41","6","Management and administration strengthening for teacher education institutions","Strengthen management and administration of teacher education institutions (TEIs)",""]],"72":[[1,"41","8","Revised curriculum implementation in teacher education institutions","Revised curriculum is implemented at TEIs;",""]],"73":[[1,"41","11","Teacher professional development programme (also read at p.41 §13)","Develop a teacher professional development programme to provide professional, long-term in-service professional teacher training and mentoring support to teachers from a designated cluster of schools within each township",""]],"74":[[1,"41","12","National Centre for Teacher Professional Development","Establishment of a National Centre for Teacher Professional Development (NCTPD) to provide long-term, essential training capacity to successfully implement the teacher professional development programme",""]],"75":[[1,"42","2","Alternative education pathways for out-of-school youth (also read at p.42 §5)","In response the MOE will put in place accessible alternative education pathway options that provide out-of-school youth with the competencies and credentials that will open the door to higher wages and lifelong learning opportunities.",""]],"76":[[1,"43","3","Alternative education coordination and provider capacity support","National AE Co-ordination Committee (AECC), AE policy and Dept. of Alternative Education capacity to support the effective and efficient co-ordination of government and non-government AE providers, community-based organisations and the private sector",""]],"77":[[1,"43","4","Alternative education baseline and database system","National AE baseline and database system design to ensure equity in the provision of AE services",""]],"78":[[1,"43","5","NGO-partnered non-formal education equivalency programmes","Non-governmental organisations (AE providers) partner with the MOE to deliver quality non-formal primary and middle school education equivalency programmes and other AE programmes for out-of-school learners",""]],"79":[[1,"43","8","Expansion of non-formal primary equivalency and literacy programmes in disadvantaged areas","Non-formal  Primary  Education  Equivalency  Programme (NFPE EP), Basic Literacy and Functional  Literacy programmes and others AE programmes  expansion in disadvantaged areas with the highest  number of children dropping out of primary school",""]],"80":[[1,"43","11","Alternative education quality standards assessment framework","Development of a national AE Quality Standards Assessment Framework (AE-QSAF) to enable senior MOE managers to access accurate and reliable data on the performance of AE service providers",""]],"81":[[1,"43","12","National certificates for alternative education programmes","Development of national certificates for AE programmes to enable students to access other learning pathways in the AE system",""]],"82":[[1,"43","13","Alternative education teacher competency development and training programme","Development of AE teacher competencies and a teacher training programme",""]],"83":[[1,"43","14","Annual quality standards assessment for alternative education providers","AE providers use the findings from annual Quality Standards Assessments to improve the implementation of AE programmes and achieve minimum national quality standards",""]],"84":[[1,"43","15","Non-formal middle school education programme","Non-formal Middle School Education Programme (NFMSEP) piloting and implementation nationally through a combination of government, non-government and private sector organisations",""]],"85":[[1,"43","16","National Youth Education Certificate pathway","National Youth Education Certificate (NYEC) as a pathway for out-of-school youth who would like to continue their alternative education into TVET, higher education and employment",""]],"86":[[1,"43","18","Alternative education pathways map","The MOE has developed an Alternative Education Pathways Map (see Diagram 10.2) to show the multiple and interconnected pathways for students to access alternative education and to progress to employment opportunities.",""]],"87":[[1,"46","3","TVET workforce development and demand-specific training (also read at p.46 §3)","Myanmar’s TVET system needs to develop a highly qualified workforce for the domestic economy in emerging industrial and service sectors, and ensure that skilled workers are able to achieve international and ASEAN TVET skills standards.",""]],"88":[[1,"46","4","TVET pathways map","The MOE has developed a TVET Pathways Map (see Diagram 10.3) to show the multiple and interconnected pathways for students to access TVET and to progress to employment opportunities.",""]],"89":[[1,"46","6","TVET access expansion for disadvantaged groups","Expanding access to TVET for various target groups including disadvantaged populations and people with disabilities",""]],"90":[[1,"46","8","Integrated TVET system establishment","Establish an integrated TVET system that strengthens access to all TVET pathways outlined in the TVET Pathways Map",""]],"91":[[1,"46","9","TVET capacity expansion and programme upgrading","Increase the capacity and upgrade existing TVET programmes",""]],"92":[[1,"46","10","Competency-based modular short courses for TVET access","Undertake competency-based modular short courses to increase access to TVET",""]],"93":[[1,"46","11","TVET centres of excellence in Yangon and Mandalay","Establish TVET Centres of Excellence (COEs) in Yangon and Mandalay regions to demonstrate best practices and to undertake research and innovation in TVET provision",""]],"94":[[1,"46","12","Stipend and scholarship expansion for disadvantaged and TVET students (also read at p.46 §16)","Expand stipends and scholarships for disadvantaged students",""]],"95":[[1,"47","3","TVET management capacity development","Undertake capacity development for TVET managers/management staff",""]],"96":[[1,"47","4","TVET teacher pedagogical and skills training programme","Provide pedagogical and specific skills training for pre-service and in-service TVET teachers",""]],"97":[[1,"47","5","Dual training systems in institutions and industry workplaces","Establish dual training systems at training institutions and industry workplaces",""]],"98":[[1,"47","6","TVET curriculum development and upgrading","Develop/upgrade TVET curricula to meet local needs and provide a balance between practical work and theory",""]],"99":[[1,"47","7","TVET quality assurance system","Establish a quality assurance system that comprises a TVET National Qualifications Framework, national skills standards, a competency-based curriculum and accreditation of institutions and individuals",""]],"100":[[1,"47","15","Strengthened TVET governance system","Establish a strengthened TVET governance system to enhance sector management and efficiency, increase access, and improve quality and relevance relating to shifting labour market demands",""]],"101":[[1,"47","16","TVET Council and local advisory boards establishment","Establish and strengthen the proposed TVET Council and local TVET advisory boards",""]],"102":[[1,"47","17","TVET financial management and monitoring system","Establish a TVET financial management and monitoring system to co-ordinate and apply the budget effectively, in a way that is made public",""]],"103":[[1,"47","18","TVET information management and data system (also read at p.47 §23)","Establishment of an information management system to collect data to better understand Myanmar’s changing TVET system and the performance of the labour market in order to inform policy decision-making",""]],"104":[[1,"47","19","TVET research and evidence-based planning programme","Conduct TVET research on skill types, localised employment needs, teacher requirements, teaching aids and pedagogies, and updated vocational subjects to support evidence-based decision-making",""]],"105":[[1,"47","20","Public-private partnerships for TVET expansion (also read at p.47 §25)","Establish public–private partnerships (PPPs) to expand access to quality TVET services, and strengthen partnerships between the public and private sector",""]],"106":[[1,"50","3","Higher education institution reform","Myanmar’s HEIs will be reformed to enable greater knowledge production and to develop highly skilled research centres to support social and economic development.",""]],"107":[[1,"51","3","Research and development centres at higher education institutions","Establish a National Research and Innovation Fund and Research and Development Centres at HEIs to benefit university teaching and learning, and develop university-managed income streams",""]],"108":[[1,"51","4","Policy and strategy for world-class national and comprehensive universities","Develop a policy and strategy for world-class national universities and comprehensive universities",""]],"109":[[1,"51","5","Higher education facilities upgrade programme","Upgrade facilities at selected HEIs",""]],"110":[[1,"51","6","E-learning centres and e-libraries enhancement in higher education institutions","Enhance the status of e-learning centres and e-libraries in HEIs",""]],"111":[[1,"51","8","Professional development for higher education faculty and laboratory technicians","Undertake professional development for faculty and laboratory technicians",""]],"112":[[1,"51","11","Equitable access to higher education programme","Equitable access to higher education programme",""]],"113":[[1,"51","12","Higher education teaching and learning environment improvement","Create a good teaching and learning environment at HEIs",""]],"114":[[1,"51","15","Higher education governance and management capacity strengthening (also read at p.51 §16)","Strategy 1: Strengthen higher education governance and  management capacity",""]],"115":[[1,"51","17","International partnerships and study tours for higher education","Undertake overseas study tours to document best practices and establish partnerships with international universities, research centres and other higher education institutions",""]],"116":[[1,"51","18","National Institute for Higher Education Development","Establish a National Institute for Higher Education Development (NIHED) to improve higher education governance and management, build individual skills and strengthen institutional capabilities",""]],"117":[[1,"51","19","Higher education governance strengthening through university charters and councils","Strengthen governance of HEIs through university charters and university councils",""]],"118":[[1,"51","20","Higher education institution autonomy and accountability reform","Strengthen autonomy and accountability of HEIs",""]],"119":[[1,"51","21","Higher education quality assurance agency (also read at p.52 §9)","Establish a Higher Education Quality Assurance Agency to lead the development of national quality standards for higher education and undertake quality assurance assessments of all HEIs",""]],"120":[[1,"52","10","Education sector coordination mechanisms","Strengthen and sustain sector-wide, sub-sector and sub-national co-ordination mechanisms",""]],"121":[[1,"52","12","Strengthening of subnational education committees","Strengthen state and region, district and township education committees to support more effective and efficient education sector co-ordination",""]],"122":[[1,"52","13","Partnerships with state and region education offices","Partnerships with state and region education offices to address the most urgent challenges in the provision of quality basic education, alternative education and TVET",""]],"123":[[1,"53","3","NESP coordination and management structures","Establish the NESP Co-ordination Committee, Programme Management Teams (PMTs) and the NESP Secretariat to support the NESP implementing departments to successfully implement NESP strategies and programmes",""]],"124":[[1,"53","5","Strengthening of HRIS, EMIS and the Education Portal","Strengthen HRIS and EMIS and develop the Education Portal to support evidence-based decision making across the national education system",""]],"125":[[1,"53","6","Performance monitoring and accountability dashboard development","Development of the Performance Monitoring and Accountability System (PeMAS) dashboard to present the most important performance monitoring data on one integrated system for easy and immediate access by senior officials",""]],"126":[[1,"53","7","Joint annual education sector performance and budget reviews (also read at p.53 §7)","Institutionalise education sector annual planning through a joint Annual Sector Performance Review and a joint Annual Sector Budget Review",""]],"127":[[1,"53","8","Basic ICT tools and new ICT pilots for education management","Provide basic ICT tools and undertake pilots using new ICTs, to strengthen education management efficiency and effectiveness at all levels of the national education system",""]],"128":[[1,"53","10","Education manager capacity strengthening (also read at p.53 §11; p.53 §12; p.53 §13)","Strengthen the capacity of education managers to successfully undertake education reforms",""]],"129":[[1,"54","2","Education pathways map implementation","The MOE has developed an Education Pathways Map (see Diagram 11.1 below) which shows the formal and alternative education pathways that students can take to achieve their career and lifelong learning aspirations.",""]],"130":[[1,"56","2","Quality-focused education investment in instructional materials and school infrastructure","there have been notable efforts made to prioritise quality-focused investments across the sector, such as instructional materials and school infrastructure.",""]],"131":[[1,"57","2","Phased implementation of the National Education Strategic Plan","In response to this situation the MOE will undertake a phased approach to implementation of the NESP.",""]],"132":[[1,"57","4","NESP annual priorities plan (also read at p.57 §6)","Under Phase 1 of the NESP the MOE will identify priority reforms on an annual basis and list them in a NESP Annual Priorities Plan.",""]]}});
